def sieve_primes(limit: int) -> list[int]:
    """All primes <= limit by the sieve of Eratosthenes."""
    flags: list[bool] = []
    for i in range(limit + 1):
        flags.append(True)
    primes: list[int] = []
    for p in range(2, limit + 1):
        if flags[p]:
            primes.append(p)
            for q in range(p * p, limit + 1, p):
                flags[q] = False
    return primes

